INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('glass', 'Glass & Ceramic', 'bi-cup-straw', '#0284c7', 'Jars, bottles, broken ceramics, mirrors, and glassware. Infinite recyclability, ideal for upcycling.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('paper', 'Paper & Cardboard', 'bi-box-seam', '#d97706', 'Corrugated boxes, newspapers, egg cartons, toilet paper rolls, and packaging materials.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('textiles', 'Textiles & Clothing', 'bi-scissors', '#e11d48', 'Old t-shirts, worn denim, single socks, bedsheets, towels, sweaters, and fabric scraps.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('plastics', 'Plastics & Polymers', 'bi-recycle', '#059669', 'Water bottles, milk jugs, food takeaway containers, bottle caps, detergent bottles, and bubble wrap.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('electronics', 'Electronics & E-Waste', 'bi-cpu', '#7c3aed', 'Old phones, keyboards, cables, broken earphones, computer mice, CDs, and tech hardware.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('metals', 'Metals & Cans', 'bi-shield-shaded', '#475569', 'Soda cans, food tin cans, wire hangers, crown bottle caps, keys, and old cookware.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('wood', 'Wood & Cork', 'bi-tree', '#92400e', 'Pallets, wine corks, popsicle sticks, broken furniture frames, and wooden scraps.');
INSERT INTO `categories` (`id`, `name`, `icon`, `color`, `description`) VALUES ('rubber_misc', 'Rubber & Household Misc', 'bi-life-preserver', '#4f46e5', 'Bicycle inner tubes, worn toothbrushes, coffee grounds, used tea bags, and household sundries.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (1, 'glass', 'Glass Mason Jar', 'glass-mason-jar', 'Clear airtight glass jar commonly used for preserves and canned goods.', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=600&auto=format&fit=crop&q=80', 'Glass takes over 1 million years to decompose in landfills. Reusing keeps durable soda-lime glass in circulation.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (2, 'glass', 'Wine Bottle', 'wine-bottle', 'Standard 750ml glass wine or beverage bottle.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop&q=80', 'Over 3 billion wine bottles are thrown away every year globally. Upcycling saves high glass-melting energy.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (3, 'glass', 'Glass Perfume Bottle', 'glass-perfume-bottle', 'Heavy-base glass fragrance bottle with atomizer pump.', 'https://images.unsplash.com/photo-1541643600914-78b084683601?w=600&auto=format&fit=crop&q=80', 'Complex metal crimp caps often cause perfume bottles to be discarded rather than recycled.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (4, 'glass', 'Chipped Ceramic Coffee Mug', 'chipped-ceramic-coffee-mug', 'Stoneware or porcelain hot beverage mug with minor rim chip.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600&auto=format&fit=crop&q=80', 'Ceramics cannot be melted in conventional municipal glass recycling furnaces; landfill is their usual fate.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (5, 'glass', 'Glass Pickle Jar', 'glass-pickle-jar', 'Wide-mouth heavy glass food jar with twist metal lid.', 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 'Large food jars represent a massive proportion of domestic glass. Thick walls make them indestructible.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (6, 'glass', 'Old Glass Chandelier Crystals & Beads', 'old-glass-chandelier-crystals-and-beads', 'Faceted glass prism crystals from old lamps or beaded jewelry.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'Lead crystal and art glass contain metal oxides that contaminate standard glass recycling streams.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (7, 'glass', 'Incandescent Light Bulb', 'incandescent-light-bulb', 'Burned-out clear or frosted filament electric bulb.', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?w=600&auto=format&fit=crop&q=80', 'Incandescent bulbs contain mixed metals and fine filament wire that cannot be recycled with bottle glass.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (8, 'paper', 'Corrugated Cardboard Box', 'corrugated-cardboard-box', 'Heavy-duty brown corrugated packaging and shipping box.', 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=600&auto=format&fit=crop&q=80', 'E-commerce packaging is the fastest growing solid waste category worldwide.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (9, 'paper', 'Egg Carton', 'egg-carton', 'Molded paper pulp carton for 12 or 30 eggs.', 'https://images.unsplash.com/photo-1587486913049-53fc88980cfc?w=600&auto=format&fit=crop&q=80', 'Molded paper pulp is biodegradable but often trashed rather than put to functional gardening use.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (10, 'paper', 'Old Newspapers', 'old-newspapers', 'Daily newsprint paper sheets.', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=600&auto=format&fit=crop&q=80', 'Newsprint ink is now mostly non-toxic soy-based, making it ideal for composting and upcycling.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (11, 'paper', 'Glossy Magazines', 'glossy-magazines', 'Full-color printed glossy magazine issues.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=600&auto=format&fit=crop&q=80', 'Glossy clay coatings make paper recycling energy intensive. Upcycling into craft preserves value.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (12, 'paper', 'Toilet Paper Rolls & Paper Towel Tubes', 'toilet-paper-rolls-and-paper-towel-tubes', 'Cardboard cylindrical inner tubes.', 'https://images.unsplash.com/photo-1584556812952-905ffd0c611a?w=600&auto=format&fit=crop&q=80', 'Millions of cardboard tubes are discarded monthly. Their uniform cylinder shape is highly versatile.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (13, 'paper', 'Cardboard Shoe Box', 'cardboard-shoe-box', 'Rigid rectangular shoe storage box with lid.', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', 'Sturdy rigid cardboard boxes with lids make premium structural organizers.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (14, 'paper', 'Cereal Box', 'cereal-box', 'Thin chipboard cardboard food packaging box.', 'https://images.unsplash.com/photo-1527515637462-cff94eecc1ac?w=600&auto=format&fit=crop&q=80', 'Thin chipboard bends and cuts cleanly, making it perfect for office paper organization.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (15, 'paper', 'Damaged Paperback Book', 'damaged-paperback-book', 'Paperback book with torn, missing, or water-damaged pages.', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600&auto=format&fit=crop&q=80', 'Glued bindings prevent paperback books from standard pulp recycling; book crafts save vintage paper.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (16, 'textiles', 'Old Cotton T-Shirt', 'old-cotton-t-shirt', 'Worn, stretched, or stained cotton crewneck shirt.', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=600&auto=format&fit=crop&q=80', 'Fast fashion dumps millions of cotton garments into landfills annually where they generate methane.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (17, 'textiles', 'Worn-Out Denim Jeans', 'worn-out-denim-jeans', 'Frayed or torn denim trousers.', 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=600&auto=format&fit=crop&q=80', 'Producing one pair of jeans requires ~7,500 liters of water. Denim is heavyweight and lasts decades.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (18, 'textiles', 'Single Odd Sock', 'single-odd-sock', 'Mismatched or single leftover cotton/wool sock.', 'https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?w=600&auto=format&fit=crop&q=80', 'Billions of lonely socks lose their partners each year. Knitted sock fabric is soft and elastic.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (19, 'textiles', 'Old Cotton Bed Sheet', 'old-cotton-bed-sheet', 'Worn or faded large cotton flat or fitted sheet.', 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=600&auto=format&fit=crop&q=80', 'Bed sheets contain several square meters of high-quality weave cotton fiber.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (20, 'textiles', 'Frayed Bath Towel', 'frayed-bath-towel', 'Frayed, thin, or discolored cotton terry cloth towel.', 'https://images.unsplash.com/photo-1616627547584-bf28cee262db?w=600&auto=format&fit=crop&q=80', 'Terry cloth loops are engineered for maximum liquid retention and scrubbing friction.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (21, 'textiles', 'Woolen Winter Sweater', 'woolen-winter-sweater', 'Shrunk, moth-eaten, or unraveling wool sweater.', 'https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=600&auto=format&fit=crop&q=80', 'Wool is a natural, breathable, premium thermal protein fiber that felts into dense fabric.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (22, 'textiles', 'Old Curtains & Window Drapes', 'old-curtains-and-window-drapes', 'Faded or outdated fabric window drapery panels.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=600&auto=format&fit=crop&q=80', 'Drapery fabrics have heavy weave counts designed to block sunlight and draft.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (23, 'textiles', 'Scrap Fabric Offcuts', 'scrap-fabric-offcuts', 'Small trimmings from sewing and tailoring projects.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=600&auto=format&fit=crop&q=80', 'Tailoring waste accounts for 15% of garment factory textile scrap.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (24, 'plastics', 'Plastic Water Bottle (PET)', 'plastic-water-bottle-pet', 'Single-use polyethylene terephthalate water bottle.', 'https://images.unsplash.com/photo-1550989460-0adf9ea622e2?w=600&auto=format&fit=crop&q=80', '1 million plastic bottles are purchased every minute around the globe; 91% are not recycled.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (25, 'plastics', '2-Liter Soda Bottle', '2-liter-soda-bottle', 'Large carbonated soft drink bottle.', 'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?w=600&auto=format&fit=crop&q=80', 'Large volumes of PET plastic take up enormous landfill volume if not recycled or repurposed.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (26, 'plastics', 'Milk Jug / Canister (HDPE)', 'milk-jug---canister-hdpe', 'Opaque high-density polyethylene gallon or 2-liter milk jug.', 'https://images.unsplash.com/photo-1563636619-e9143da7973b?w=600&auto=format&fit=crop&q=80', 'HDPE (#2) plastic is rigid, durable, non-toxic, and resistant to UV breakdown.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (27, 'plastics', 'Plastic Takeaway Food Containers', 'plastic-takeaway-food-containers', 'Clear or black polypropylene (PP #5) food tubs with lids.', 'https://images.unsplash.com/photo-1584473457406-6240486418e9?w=600&auto=format&fit=crop&q=80', 'Takeaway food containers represent major urban plastic waste; food-safe PP is durable and washable.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (28, 'plastics', 'Plastic Bottle Caps', 'plastic-bottle-caps', 'Small colored polypropylene screw bottle caps.', 'https://images.unsplash.com/photo-1618477461853-cf6ed80faba5?w=600&auto=format&fit=crop&q=80', 'Bottle caps are frequently discarded into marine ecosystems where birds mistake them for food.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (29, 'plastics', 'Detergent Bottle (Heavy Duty)', 'detergent-bottle-heavy-duty', 'Heavy-duty HDPE plastic laundry detergent or bleach bottle.', 'https://images.unsplash.com/photo-1585421514738-01798e348b17?w=600&auto=format&fit=crop&q=80', 'Thick-walled industrial plastics withstand years of outdoor weathering.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (30, 'plastics', 'Bubble Wrap Packaging', 'bubble-wrap-packaging', 'Flexible cushioning polyethylene bubble sheeting.', 'https://images.unsplash.com/photo-1589939705384-5185137a7f0f?w=600&auto=format&fit=crop&q=80', 'Bubble wrap cannot be collected in curbside recycling bins because it jams sorting machinery.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (31, 'plastics', 'Plastic Shopping Bags', 'plastic-shopping-bags', 'Thin HDPE or LDPE carryout grocery bags.', 'https://images.unsplash.com/photo-1597484661643-2f5fef640dd1?w=600&auto=format&fit=crop&q=80', '500 billion plastic bags are used annually with an average lifespan of only 12 minutes before disposal.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (32, 'electronics', 'Broken Smartphone', 'broken-smartphone', 'Outdated or broken-screen smartphone with functional motherboard.', 'https://images.unsplash.com/photo-1511707171634-5f897ff02aa9?w=600&auto=format&fit=crop&q=80', 'E-waste is the fastest growing waste stream worldwide, containing precious metals and toxic components.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (33, 'electronics', 'Old Laptop Keyboard', 'old-laptop-keyboard', 'Non-functioning membrane or scissor-switch laptop keyboard.', 'https://images.unsplash.com/photo-1587829741301-dc798b83add3?w=600&auto=format&fit=crop&q=80', 'Keycaps are molded from durable ABS plastic that can be repurposed individually.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (34, 'electronics', 'Broken Earphones (One Side Working)', 'broken-earphones-one-side-working', 'Wired 3.5mm stereo earbuds with one dead channel.', 'https://images.unsplash.com/photo-1505740420928-5e560c06d30e?w=600&auto=format&fit=crop&q=80', 'Wired earphones contain copper wire, rare earth magnets, and functioning condenser microphones.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (35, 'electronics', 'Dead USB Cable', 'dead-usb-cable', 'Frayed or non-charging USB charging/data cable.', 'https://images.unsplash.com/photo-1588508065123-287b28e013da?w=600&auto=format&fit=crop&q=80', 'USB cables are discarded by the tens of millions when small connector pins wear out.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (36, 'electronics', 'Old Computer Mouse', 'old-computer-mouse', 'Outdated ball or optical USB corded mouse.', 'https://images.unsplash.com/photo-1615663245857-ac93bb7c39e7?w=600&auto=format&fit=crop&q=80', 'Ergonomically contoured plastic casings can be transformed into ergonomic household tools.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (37, 'electronics', 'Compact Discs (CDs & DVDs)', 'compact-discs-cds-and-dvds', 'Scratched optical media discs.', 'https://images.unsplash.com/photo-1541701494587-cb58502866ab?w=600&auto=format&fit=crop&q=80', 'Polycarbonate plastic with aluminum and lacquer layers is nearly impossible to recycle conventionally.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (38, 'electronics', 'Broken Tablet Screen / Outer Frame', 'broken-tablet-screen---outer-frame', 'Cracked screen tablet chassis.', 'https://images.unsplash.com/photo-1544244015-0df4b3ffc6b0?w=600&auto=format&fit=crop&q=80', 'Tablet bodies feature rigid aluminum shells and high-grade LED backlights.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (39, 'electronics', 'Old Computer 12V Cooling Fan', 'old-computer-12v-cooling-fan', '80mm or 120mm brushless DC case fan.', 'https://images.unsplash.com/photo-1591799264318-7e6ef8ddb7ea?w=600&auto=format&fit=crop&q=80', 'Brushless DC fans run smoothly for up to 50,000 continuous hours without maintenance.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (40, 'metals', 'Aluminum Soda Can', 'aluminum-soda-can', '330ml / 500ml thin aluminum beverage can.', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=600&auto=format&fit=crop&q=80', 'Aluminum is 100% endlessly recyclable, but crafting gives immediate zero-energy reuse.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (41, 'metals', 'Tin Food / Soup Can', 'tin-food---soup-can', 'Steel tinplate canned food container.', 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 'Steel cans have outstanding structural strength and magnetic properties.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (42, 'metals', 'Wire Coat Hanger', 'wire-coat-hanger', 'Thin steel wire dry-cleaner clothes hanger.', 'https://images.unsplash.com/photo-1582719478250-c89cae4dc85b?w=600&auto=format&fit=crop&q=80', 'Dry cleaner hangers are awkward in recycling systems and tangle municipal sorting belts.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (43, 'metals', 'Metal Crown Bottle Caps', 'metal-crown-bottle-caps', 'Crimped metal bottle caps from glass soda/beer bottles.', 'https://images.unsplash.com/photo-1563245372-f21724e3856d?w=600&auto=format&fit=crop&q=80', 'Small metal caps fall through recycling screens; capturing them creates artisan metal crafts.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (44, 'metals', 'Old Brass & Iron Keys', 'old-brass-and-iron-keys', 'Obsolete door and padlock metal keys.', 'https://images.unsplash.com/photo-1582139329536-e7284fece509?w=600&auto=format&fit=crop&q=80', 'Solid brass and nickel keys have high metal value and antique aesthetic appeal.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (45, 'metals', 'Burnt / Scratched Cooking Pan', 'burnt---scratched-cooking-pan', 'Non-stick frying pan with damaged coating or warped base.', 'https://images.unsplash.com/photo-1584990347449-399bfb0c4874?w=600&auto=format&fit=crop&q=80', 'Damaged PTFE Teflon pans are unsafe for cooking but make heavy-duty outdoor basins.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (46, 'metals', 'Metal Cutlery (Bent Spoons & Forks)', 'metal-cutlery-bent-spoons-and-forks', 'Bent, mismatched, or tarnished stainless steel/silverplate silverware.', 'https://images.unsplash.com/photo-1584308666744-24d5c474f2ae?w=600&auto=format&fit=crop&q=80', 'Stainless steel flatware is extremely tough, weather-resistant, and pliable with heat or pliers.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (47, 'wood', 'Wooden Shipping Pallet', 'wooden-shipping-pallet', 'Industrial pine shipping pallet.', 'https://images.unsplash.com/photo-1586528116311-ad8dd3c8310d?w=600&auto=format&fit=crop&q=80', 'Over 2 billion wooden pallets circulate globally; upcycling untreated HT pallets prevents forest logging.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (48, 'wood', 'Wine Corks (Natural Cork)', 'wine-corks-natural-cork', 'Cylindrical cork stoppers from wine bottles.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop&q=80', 'Natural cork is the harvested bark of cork oak trees. It is water-resistant, buoyant, and resilient.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (49, 'wood', 'Wooden Ice Cream Popsicle Sticks', 'wooden-ice-cream-popsicle-sticks', 'Birch wood craft or ice cream treat sticks.', 'https://images.unsplash.com/photo-1516054575922-f0b8eeadec1a?w=600&auto=format&fit=crop&q=80', 'Clean birch wood sticks are lightweight, uniform, and easily joined with simple craft adhesives.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (50, 'wood', 'Broken Wooden Picture Frame', 'broken-wooden-picture-frame', 'Framed moulding with broken glass or detached corners.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'Solid timber mouldings can be repurposed with wire, mesh, or chalk for multi-purpose utility.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (51, 'rubber_misc', 'Old Bicycle Inner Tube', 'old-bicycle-inner-tube', 'Punctured butyl rubber bicycle tire inner tube.', 'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=600&auto=format&fit=crop&q=80', 'Butyl rubber is virtually indestructible, UV-resistant, and possesses incredible elastic tension.');
INSERT INTO `items` (`id`, `category_id`, `name`, `slug`, `description`, `image_url`, `disposal_impact`) VALUES (52, 'rubber_misc', 'Worn-Out Plastic Toothbrush', 'worn-out-plastic-toothbrush', 'Toothbrush with frayed nylon bristles.', 'https://images.unsplash.com/photo-1559591937-e1032b4b4556?w=600&auto=format&fit=crop&q=80', 'Over 1 billion plastic toothbrushes are trashed in the US alone each year; they do not biodegrade.');
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (1, 1, 1, 'Mason Jar Kitchen Herb Garden', 'reuse', 'Easy', 'Low', 80, '20 mins', '["Mason jar", "Potting soil", "Small pebbles", "Herb seeds or cuttings", "Twine"]', '["Clean and sterilize the mason jar with warm soapy water.", "Add a 1-inch layer of small pebbles or gravel at the bottom for root drainage.", "Fill the jar with quality organic potting soil, leaving an inch at the top.", "Plant your herb seeds (mint, basil, or coriander) and pat down lightly.", "Water gently and place on a sunny kitchen windowsill."]', 'Keeps culinary herbs fresh within arm''s reach while eliminating plastic grocery store herb packaging.', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=600&auto=format&fit=crop&q=80', 'approved', 22, 137);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (2, 1, 1, 'Fairy Light Bedside Lantern', 'reuse', 'Easy', 'Low', 150, '10 mins', '["Mason jar", "Battery-powered LED copper string lights", "Burlap ribbon or lace", "Glue"]', '["Wrap burlap ribbon or decorative lace around the jar waist and fasten with a drop of glue.", "Insert battery-operated warm micro-LED string lights into the jar.", "Secure the battery pack under the lid with double-sided tape.", "Turn on for an enchanting, ambient eco-lamp."]', 'Creates low-energy ambient lighting using repurposed jars without high electric draw.', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=600&auto=format&fit=crop&q=80', 'approved', 29, 154);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (3, 1, 1, 'Layered Meal Prep Salad Shaker', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Mason jar with tight lid", "Salad greens", "Dressing", "Vegetables and protein"]', '["Pour salad dressing directly into the bottom of the jar so greens stay crisp.", "Layer hard vegetables like chickpeas, cucumbers, and diced carrots next.", "Top with leafy greens and seeds.", "Seal tightly and refrigerate for up to 5 days. Shake into a bowl when ready to eat."]', 'Replaces single-use plastic takeaway salad containers.', 'https://images.unsplash.com/photo-1590490360182-c33d57733427?w=600&auto=format&fit=crop&q=80', 'approved', 36, 171);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (4, 2, 1, 'Self-Watering Vacation Plant Spike', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Empty wine bottle", "Water", "Terracotta plant spike or perforated cork"]', '["Thoroughly wash the wine bottle and remove paper labels by soaking in warm soapy water.", "Fill the bottle to the brim with clean water.", "Insert a terracotta plant watering spike or cork with a small hole drilled through.", "Invert quickly and press deep into the soil of your potted plant."]', 'Keeps houseplants hydrated for up to two weeks without electricity or plastic automated drip systems.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop&q=80', 'approved', 43, 188);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (5, 2, 1, 'Rustic Taper Candle Holder', 'reuse', 'Easy', 'Low', 50, '15 mins', '["Clean wine bottle", "Taper candle", "Twine", "Matches"]', '["Clean the bottle exterior and strip off adhesive residue.", "Wrap rustic jute twine around the bottle neck 8-10 times and tie off.", "Shave the base of a taper candle slightly if needed to fit snugly into the bottle mouth.", "Light candle and let wax drips create an artistic vintage patina."]', 'Transforms discarded glassware into moody restaurant-style candle decor.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop&q=80', 'approved', 50, 205);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (6, 2, 1, 'Kitchen Olive Oil & Vinegar Dispenser', 'reuse', 'Medium', 'Low', 60, '20 mins', '["Clean wine bottle", "Oil pour spout nozzle", "Chalkboard label", "Chalk pen"]', '["Sanitize the bottle with boiling water and air dry completely.", "Stick a waterproof chalkboard label on the body and write ''EVOO'' or ''Balsamic''.", "Fill with bulk olive oil or infused vinegar.", "Push in a silicone oil pourer spout."]', 'Allows buying cooking oils in bulk containers, cutting down on plastic bottles.', 'https://images.unsplash.com/photo-1510812431401-41d2bd2722f3?w=600&auto=format&fit=crop&q=80', 'approved', 57, 222);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (7, 3, 1, 'Luxury Reed Fragrance Diffuser', 'reuse', 'Easy', 'Low', 90, '15 mins', '["Empty perfume bottle", "Pliers", "Carrier oil (almond or mineral oil)", "Essential oils", "Rattan reed sticks"]', '["Use small pliers to gently pry open the crimped metal spray collar from the glass rim.", "Rinse any perfume residue with rubbing alcohol.", "Mix 70% carrier oil with 30% essential oils (lavender, citrus, or cedarwood).", "Pour into the bottle and insert 4-5 natural rattan reed sticks. Flip weekly."]', 'Replaces store-bought commercial synthetic air fresheners with pure botanicals.', 'https://images.unsplash.com/photo-1541643600914-78b084683601?w=600&auto=format&fit=crop&q=80', 'approved', 64, 239);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (8, 3, 1, 'Miniature Flower Bud Vase', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Perfume bottle", "Pliers", "Single garden flower bud", "Water"]', '["Uncrimp and remove the sprayer mechanism.", "Wash the interior with warm soapy water until scent is dissipated.", "Fill with clean water and insert a single wildflower, baby''s breath, or rosebud for a chic desk accent."]', 'Creates bespoke minimalist floral decor from luxury glass bottles.', 'https://images.unsplash.com/photo-1541643600914-78b084683601?w=600&auto=format&fit=crop&q=80', 'approved', 71, 256);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (9, 3, 1, 'Vintage Trinket Dressing Table Accent', 'reuse', 'Medium', 'Low', 40, '25 mins', '["Perfume bottle", "Gold metallic spray or acrylic paint", "Ribbon"]', '["Clean bottle thoroughly.", "Mask off geometric stripes with painter''s tape.", "Coat with metallic spray paint and let dry.", "Remove tape to reveal contrasting frosted glass patterns."]', 'Upcycles decorative glass into artisan dressing vanity decor.', 'https://images.unsplash.com/photo-1541643600914-78b084683601?w=600&auto=format&fit=crop&q=80', 'approved', 78, 273);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (10, 4, 1, 'Succulent Mug Planter with Drainage', 'reuse', 'Easy', 'Low', 50, '15 mins', '["Chipped ceramic mug", "Gravel / pumice stones", "Cactus & succulent soil", "Small succulent cutting"]', '["Smooth down any sharp chipped edge with fine-grit sandpaper.", "Place a 1-inch layer of coarse gravel or volcanic pumice at the bottom to hold excess water.", "Add succulent soil mix and embed your succulent.", "Top with decorative pebbles and place in bright indirect sunlight."]', 'Repurposes non-recyclable chipped ceramics into thriving indoor greenery.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600&auto=format&fit=crop&q=80', 'approved', 85, 290);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (11, 4, 1, 'Desktop Pen & Stationery Caddy', 'reuse', 'Easy', 'Free', 0, '5 mins', '["Ceramic mug", "Sandpaper"]', '["Sand down the chipped rim until completely smooth to the touch.", "Place on office desk or study table.", "Sort highlighters, pens, ruler, and scissors upright."]', 'Zero-cost durable organization that keeps stationery organized.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600&auto=format&fit=crop&q=80', 'approved', 92, 307);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (12, 4, 1, 'Mosaic Garden Stepping Stone Inlay', 'recycle', 'Advanced', 'Low', 120, '1 hour', '["Chipped ceramic mug", "Hammer", "Cloth towel", "Safety goggles", "Tile grout or cement"]', '["Wrap the chipped mug securely in a thick cloth towel.", "Tap gently with a hammer wearing eye protection to break into 1-inch decorative shards.", "Arrange colorful mosaic shards into wet garden stepping stone cement or mosaic tile trivet.", "Grout over joints and wipe clean with a sponge once cured."]', 'Diverts ceramics completely from landfills by converting them into long-lasting garden art.', 'https://images.unsplash.com/photo-1514432324607-a09d9b4aefdd?w=600&auto=format&fit=crop&q=80', 'approved', 99, 324);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (13, 5, 1, 'Kitchen Pantry Dry Spice & Pulse Dispenser', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Clean pickle jar", "Baking soda and vinegar", "Chalkboard label or marker"]', '["Soak jar and lid in warm water with baking soda and dish soap to neutralize lingering pickle brine odor.", "Dry completely.", "Label front with lentils, rice, pasta, or loose tea.", "Store in a clutter-free kitchen pantry."]', 'Replaces plastic pantry airtight containers with reusable, zero-chemical glass storage.', 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 'approved', 21, 341);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (14, 5, 1, 'DIY Winter Snow Globe', 'reuse', 'Medium', 'Low', 80, '30 mins', '["Pickle jar with leakproof lid", "Waterproof plastic figurine", "Epoxy glue", "Glycerin", "Biodegradable glitter", "Distilled water"]', '["Glue the figurine securely to the inside surface of the metal lid using waterproof epoxy.", "Fill jar nearly to top with distilled water, 1 teaspoon glycerin (for slow float), and glitter.", "Screw lid tightly with a bead of silicone around threads to seal permanently. Invert and enjoy."]', 'Creates a classic nostalgic keepsake using recycled packaging.', 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 'approved', 28, 358);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (15, 5, 1, 'Emergency Match & Firefly Lantern', 'reuse', 'Easy', 'Low', 30, '15 mins', '["Pickle jar", "Rough sandpaper", "Strike-anywhere matches"]', '["Cut a round piece of rough grit sandpaper to fit inside the jar lid and glue it down.", "Fill jar with matches. The seal keeps matches 100% dry during monsoon or camping, with striker built into lid."]', 'Durable, waterproof outdoor camping supply made from discarded goods.', 'https://images.unsplash.com/photo-1584269600464-37b1b58a9fe7?w=600&auto=format&fit=crop&q=80', 'approved', 35, 375);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (16, 6, 1, 'Rainbow Sun-Catcher Window Mobile', 'reuse', 'Easy', 'Low', 40, '20 mins', '["Glass prism crystals", "Fishing line or nylon beading thread", "Small wooden stick or metal ring"]', '["Cut 3-4 strands of clear nylon fishing line at varying lengths (15-30cm).", "Tie glass crystals to the ends securely.", "Attach strings to a small drift wood stick or copper ring.", "Hang directly in front of a south-facing sunny window to cast dancing rainbows."]', 'Transforms vintage broken light fittings into mood-lifting optical rainbows.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 42, 392);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (17, 6, 1, 'Melodic Glass & Metal Wind Chime', 'reuse', 'Medium', 'Low', 70, '40 mins', '["Glass crystals", "Wire coat hanger", "Nylon cord", "Beads"]', '["Bend wire coat hanger into a circular hoop.", "String crystals interspersed with small metal washers.", "Suspend so gentle breezes make them chime with delicate crystal tones."]', 'Handmade soothing garden art from discarded hardware.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 49, 409);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (18, 6, 1, 'Jeweled Artisan Ribbon Bookmark', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Single glass crystal", "Satin ribbon", "Needle and thread"]', '["Cut a 30cm length of luxurious scrap ribbon.", "Stitch the glass crystal to one end as a weighted counterweight.", "Slide into favorite novel or journal."]', 'A gorgeous, heirloom-quality reading accessory.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 56, 426);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (19, 7, 1, 'Hanging Air Plant Terrarium', 'reuse', 'Medium', 'Low', 60, '30 mins', '["Burnt-out light bulb", "Needle-nose pliers", "Safety glasses & gloves", "Jute twine", "Tillandsia air plant"]', '["Put on eye protection and thick gloves.", "Use pliers to gently twist off the brass solder contact point at the bulb base.", "Carefully break the black glass insulator and pull out the filament stem.", "Smooth the interior edge.", "Wrap twine around the threaded base, insert an air plant and hang."]', 'Converts toxic e-waste bulbs into suspended botanical art.', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?w=600&auto=format&fit=crop&q=80', 'approved', 63, 443);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (20, 7, 1, 'Festive Holiday Tree Ornament', 'reuse', 'Easy', 'Low', 40, '20 mins', '["Burnt-out bulb", "Acrylic craft paints", "Glitter", "Mod Podge glue", "Ribbon"]', '["Paint the bulb white as a snowman base or deep red/gold.", "Add facial features or painted snowflakes.", "Loop ribbon around the metal base and hot glue to form a hanging loop."]', 'Saves buying fragile plastic holiday decorations year after year.', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?w=600&auto=format&fit=crop&q=80', 'approved', 70, 460);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (21, 7, 1, 'Mini Spice Dispenser or Bud Vase', 'reuse', 'Medium', 'Free', 0, '25 mins', '["Hollowed light bulb", "Wire loop base stand", "Single stem flower"]', '["Hollow out filament as described.", "Bend a piece of stiff wire or coat hanger into a stabilizing circular stand.", "Fill with water and drop in a fresh cutting."]', 'Creates conversation-starting desktop minimalist chemistry style decor.', 'https://images.unsplash.com/photo-1507668077129-56e32842fceb?w=600&auto=format&fit=crop&q=80', 'approved', 77, 127);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (22, 8, 1, 'Modular Pet Castle / Cat Playhouse', 'reuse', 'Easy', 'Free', 0, '30 mins', '["Large cardboard box", "Utility box cutter", "Pencil", "Non-toxic glue"]', '["Sketch arched doorway and window portals on the sides with pencil.", "Carefully cut along outlines with utility knife.", "Score flaps to fold into battlements or sloping roof.", "Place favorite pet blanket inside for an instant cozy hideaway."]', 'Zero-cost pet entertainment that can be fully composted or recycled at end of life.', 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=600&auto=format&fit=crop&q=80', 'approved', 84, 144);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (23, 8, 1, 'Custom Wardrobe & Drawer Dividers', 'reuse', 'Easy', 'Free', 0, '25 mins', '["Cardboard box flaps", "Ruler", "Scissors or cutter", "Wrapping paper or tape"]', '["Measure the depth and width of your sock or underwear drawer.", "Cut cardboard strips matching drawer depth.", "Cut interlocking half-slits halfway through each strip at 3-inch intervals.", "Interlock strips in a grid pattern to create neat compartmental dividers."]', 'Organizes cluttered dressers without spending money on plastic drawer bins.', 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=600&auto=format&fit=crop&q=80', 'approved', 91, 161);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (24, 8, 1, 'Ergonomic Desktop Laptop Riser', 'reuse', 'Medium', 'Free', 0, '20 mins', '["Stiff corrugated cardboard", "Ruler", "Marker", "Utility blade"]', '["Measure laptop base width and desired 15-degree tilt angle.", "Cut two identical wedge triangles with front lip notch.", "Cut a cross-brace strut with corresponding slots to join the two sides.", "Assemble stand to elevate laptop screen to eye level, improving posture and laptop cooling."]', 'Improves ergonomics and laptop ventilation without purchasing aluminum risers.', 'https://images.unsplash.com/photo-1530587191325-3db32d826c18?w=600&auto=format&fit=crop&q=80', 'approved', 98, 178);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (25, 9, 1, 'Biodegradable Seed Starter Tray', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Paper egg carton", "Seed starting potting soil", "Vegetable / flower seeds", "Water spray bottle"]', '["Poke a pinhole at the bottom of each egg cup for drainage.", "Fill each cup 3/4 full with seedling mix.", "Place 2 seeds per cup and water with spray bottle.", "When seedlings sprout and develop true leaves, cut cups apart and plant the entire biodegradable paper cup directly into the ground."]', 'Completely eliminates plastic seedling nursery pots and prevents root transplant shock.', 'https://images.unsplash.com/photo-1587486913049-53fc88980cfc?w=600&auto=format&fit=crop&q=80', 'approved', 20, 195);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (26, 9, 1, 'Jewelry & Sewing Bobbin Tray', 'reuse', 'Easy', 'Low', 20, '20 mins', '["Egg carton", "Acrylic paint", "Brush"]', '["Trim the lid off the carton.", "Paint carton in pastel mint or blush pink acrylic.", "Use individual cups to store rings, earrings, cufflinks, thimbles, and sewing thread bobbins in drawers."]', 'Neat zero-clutter dresser organization from 100% recycled paper.', 'https://images.unsplash.com/photo-1587486913049-53fc88980cfc?w=600&auto=format&fit=crop&q=80', 'approved', 27, 212);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (27, 9, 1, 'DIY Natural Campfire & Barbecue Fire Starters', 'recycle', 'Easy', 'Free', 0, '15 mins', '["Egg carton cups", "Dryer lint or sawdust", "Melted candle wax scraps"]', '["Tear egg cups apart.", "Stuff each cup with dry lint, cotton scraps, or wood shavings.", "Pour melted leftover candle wax over the lint to bind.", "Light the cardboard rim when lighting campfires or charcoal grills."]', 'Combines three household waste streams into a high-performance fire starter.', 'https://images.unsplash.com/photo-1587486913049-53fc88980cfc?w=600&auto=format&fit=crop&q=80', 'approved', 34, 229);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (28, 10, 1, 'Chic Eco-Friendly Gift Wrapping with Jute Twine', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Clean newspaper pages (crossword or comic sections work great)", "Scissors", "Jute twine or dried leaf", "Tape"]', '["Select engaging sections like black-and-white print, puzzles, or maps.", "Wrap package smoothly around gift box and secure with minimal tape.", "Tie with rustic jute twine and tuck in a fresh sprig of rosemary or cinnamon stick."]', 'Eliminates glossy, non-recyclable metallic gift wrapping paper.', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=600&auto=format&fit=crop&q=80', 'approved', 41, 246);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (29, 10, 1, 'Garden Weed Suppressing Sheet Mulch', 'recycle', 'Easy', 'Free', 0, '30 mins', '["Old newspaper sheets", "Water", "Garden mulch or dry leaves"]', '["Lay 5-8 layers of wet newspaper directly over weed-infested garden soil.", "Overlap edges by 4 inches to block all sunlight.", "Cover with 2 inches of compost, shredded bark, or leaves. The paper suffocates weeds and breaks down into rich organic earthworm food."]', 'Natural weed control without toxic synthetic chemical herbicides.', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=600&auto=format&fit=crop&q=80', 'approved', 48, 263);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (30, 10, 1, 'Streak-Free Window & Mirror Cleaner', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Crumped dry newspaper", "50/50 White vinegar and water spray"]', '["Spray glass or car windscreen with vinegar solution.", "Use crumpled newspaper to vigorously buff in circular motions.", "The tight fibers and ink act as a micro-polishing agent with zero lint."]', 'Cleaner mirrors and windows without buying disposable microfiber wipes.', 'https://images.unsplash.com/photo-1585829365295-ab7cd400c167?w=600&auto=format&fit=crop&q=80', 'approved', 55, 280);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (31, 11, 1, 'Coiled Paper Drink Coasters', 'reuse', 'Medium', 'Low', 30, '45 mins', '["Magazine pages", "PVA glue", "Toothpick or thin skewer", "Clear varnish"]', '["Tear out vibrant color pages.", "Roll each page tightly around a skewer to form a long thin paper straw.", "Flatten straw and coil tightly in a spiral, gluing continuously along the edge.", "Seal finished coaster with water-resistant varnish."]', 'Durable, heat-resistant, moisture-repellent coasters with stunning kaleidoscopic colors.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=600&auto=format&fit=crop&q=80', 'approved', 62, 297);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (32, 11, 1, 'Folded Origami Holiday Gift Bows', 'reuse', 'Easy', 'Free', 0, '20 mins', '["Colorful magazine page", "Ruler", "Scissors", "Stapler or double-sided tape"]', '["Cut page into 9 strips of varying lengths (3 long, 3 medium, 2 short, 1 loop).", "Twist each strip into an infinity figure-eight loop.", "Stack loops in a concentric flower pattern and secure center loop with tape."]', 'Replaces plastic single-use adhesive bow packaging.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=600&auto=format&fit=crop&q=80', 'approved', 69, 314);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (33, 11, 1, 'Woven Paper Storage Basket', 'reuse', 'Advanced', 'Low', 50, '1.5 hours', '["20 magazine pages", "Glue stick", "Cardboard base square"]', '["Fold pages into stiff 1-inch flat strips.", "Weave strips in an over-under checkerboard pattern starting from the base.", "Fold upwards and weave walls. Secure top edge with folded rim strip and glue."]', 'Sturdy artisanal desktop organizing basket made 100% from throwaway paper.', 'https://images.unsplash.com/photo-1544716278-ca5e3f4abd8c?w=600&auto=format&fit=crop&q=80', 'approved', 76, 331);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (34, 12, 1, 'Tangle-Free Cable & Cord Organizers', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Cardboard tubes", "Marker or washi tape", "Loose USB cables"]', '["Neatly coil charging cables, audio cords, and appliance cables into an oblong loop.", "Slide coiled cord inside the cardboard tube.", "Label the outside (e.g., ''Type-C'', ''HDMI'', ''Phone Charger''). Line tubes vertically in a shoe box."]', 'Completely solves cable drawer tangle chaos with zero plastic ties.', 'https://images.unsplash.com/photo-1584556812952-905ffd0c611a?w=600&auto=format&fit=crop&q=80', 'approved', 83, 348);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (35, 12, 1, 'Biodegradable Seedling Starter Pots', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Toilet paper rolls", "Scissors", "Potting soil"]', '["Cut toilet paper roll in half crosswise.", "Make four 1/2-inch vertical snips at one end.", "Fold the four flaps inward like a cardboard shipping box bottom to create a self-supporting base.", "Fill with soil, plant seeds, and plant directly into garden beds."]', 'Zero-waste planting pots that dissolve naturally into garden soil.', 'https://images.unsplash.com/photo-1584556812952-905ffd0c611a?w=600&auto=format&fit=crop&q=80', 'approved', 90, 365);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (36, 12, 1, 'Desk Stationery Pen Tower', 'reuse', 'Easy', 'Low', 30, '25 mins', '["5-7 cardboard tubes", "Acrylic paint or patterned paper", "Cardboard base sheet", "Glue"]', '["Cut tubes at staggered heights (2 inches, 3 inches, 4 inches, 5 inches).", "Paint or wrap in decorative paper.", "Glue tubes together in a honeycomb cluster onto the base plate."]', 'Tiered desktop organizer for markers, pens, rulers, and scissors.', 'https://images.unsplash.com/photo-1584556812952-905ffd0c611a?w=600&auto=format&fit=crop&q=80', 'approved', 97, 382);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (37, 13, 1, 'Hidden Desk Charging Strip Station', 'reuse', 'Easy', 'Low', 20, '20 mins', '["Shoe box", "Power strip with surge protector", "Utility knife", "Metal eyelets or decorative tape"]', '["Cut a neat notch at the lower back edge of the shoe box for the power strip main cord.", "Cut 4-5 neat round holes along the front long side for device charging cables.", "Place power strip and adapters inside.", "Plug in phones and tablets through the neat front holes and close lid."]', 'Hides unsightly cable tangles and adapters behind a tidy decorative box.', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', 'approved', 19, 399);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (38, 13, 1, 'Craft Ribbon & Twine Dispenser', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Shoe box", "Wooden dowel or pencil", "Scissors", "Ribbon spools"]', '["Skewer ribbon spools along a wooden dowel or knitting needle.", "Punch two holes on opposite sides of the box to suspend the dowel inside.", "Punch matching eyelet holes in front and pull ribbon ends through for smooth tangle-free pulling."]', 'Keeps craft spools unraveled, clean, and dust-free.', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', 'approved', 26, 416);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (39, 13, 1, 'Tabletop Mini Foosball Game', 'reuse', 'Medium', 'Low', 60, '45 mins', '["Shoe box", "4 wooden dowels", "10 wooden clothespins", "Ping pong ball", "Utility knife"]', '["Cut goal openings on both short ends of the shoe box.", "Puncture 4 aligned holes across each long side.", "Insert wooden dowels through box, clip clothespins as players (2 per team on each rod).", "Drop ping pong ball and spin dowels to play."]', 'Fun STEM recycling craft for kids and family game night.', 'https://images.unsplash.com/photo-1549298916-b41d501d3772?w=600&auto=format&fit=crop&q=80', 'approved', 33, 433);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (40, 14, 1, 'Angled Desktop Magazine & Document File Holder', 'reuse', 'Easy', 'Low', 30, '20 mins', '["Cereal box", "Ruler", "Scissors or craft cutter", "Decorative wrapping paper or paint", "Glue"]', '["Tape the top cereal flaps shut securely.", "Draw a diagonal line on the side starting 4 inches from bottom up to top corner.", "Cut along lines to create standard angled magazine holder silhouette.", "Cover with marble contact paper or paint."]', 'Replaces costly plastic office file holders on desks and bookshelves.', 'https://images.unsplash.com/photo-1527515637462-cff94eecc1ac?w=600&auto=format&fit=crop&q=80', 'approved', 40, 450);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (41, 14, 1, 'Artisan Bookmarks & Luggage Tags', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Cereal box chipboard", "Hole punch", "Twine or ribbon", "Marker"]', '["Cut chipboard into 2x6 inch rectangular strips.", "Round corners with scissors.", "Punch hole at top center and thread yarn.", "Decorate with inspiring quotes, hand lettering, or pressed botanicals."]', 'Sturdy, non-bending bookmarks created from clean cereal box cardstock.', 'https://images.unsplash.com/photo-1527515637462-cff94eecc1ac?w=600&auto=format&fit=crop&q=80', 'approved', 47, 467);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (42, 14, 1, 'Drawer Divider Compartments for Small Accessories', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Cereal box", "Scissors"]', '["Cut off the bottom 3 inches of the box to form a shallow rectangular open tray.", "Slide into vanity or desk drawers to separate clips, jewelry, or USB drives."]', 'Zero-cost instant compartmentalization.', 'https://images.unsplash.com/photo-1527515637462-cff94eecc1ac?w=600&auto=format&fit=crop&q=80', 'approved', 54, 134);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (43, 15, 1, 'Secret Hollow Book Valuables Safe', 'reuse', 'Medium', 'Low', 40, '45 mins', '["Thick damaged book", "PVA craft glue & water", "Utility craft knife", "Ruler", "Wax paper"]', '["Open the first 15-20 pages and wrap them in wax paper to protect them.", "Mix 50% PVA glue with 50% water and brush the outside page edges shut.", "Let dry with weight on top.", "Measure a 1-inch interior border and hollow out the center block using a craft knife.", "Coat inside with glue and store keepsakes."]', 'Conceals jewelry or valuables seamlessly on any bookshelf.', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600&auto=format&fit=crop&q=80', 'approved', 61, 151);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (44, 15, 1, 'Vintage Silhouette Wall Art Print', 'reuse', 'Easy', 'Free', 0, '20 mins', '["Book page with text", "Printer or black ink/brush", "Picture frame"]', '["Carefully tear out an evocative page of typography.", "Use home printer or calligraphy brush to print a silhouette (tree, bird, quote) directly over the text.", "Mount inside a frame for instant literary gallery art."]', 'Artistic decor celebrating classic typography.', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600&auto=format&fit=crop&q=80', 'approved', 68, 168);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (45, 15, 1, 'Folded Paper Botanical Roses', 'reuse', 'Medium', 'Free', 0, '30 mins', '["Book pages", "Scissors", "Floral wire or stick", "Hot glue"]', '["Cut book pages into petal spirals.", "Roll paper tightly from outer edge inward to form dimensional rose blossoms.", "Glue base to floral wire stem for a maintenance-free everlasting bouquet."]', 'Everlasting literary bouquets for weddings and home styling.', 'https://images.unsplash.com/photo-1544947950-fa07a98d237f?w=600&auto=format&fit=crop&q=80', 'approved', 75, 185);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (46, 16, 1, 'No-Sew Reusable Grocery Market Tote Bag', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Old cotton t-shirt", "Sharp fabric scissors"]', '["Lay t-shirt flat.", "Cut off sleeves to create tote handles.", "Cut a wider oval neckline to enlarge bag opening.", "Turn shirt inside out and cut 1-inch vertical fringe strips along the bottom hem.", "Tie opposite fringe strips into double knots tightly. Flip right-side out."]', 'Holds up to 10kg of produce with stretchable, washable cotton comfort.', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=600&auto=format&fit=crop&q=80', 'approved', 82, 202);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (47, 16, 1, 'Braided Dog Tug Rope Toy', 'reuse', 'Easy', 'Free', 0, '20 mins', '["Cotton t-shirt", "Scissors"]', '["Cut t-shirt into six 2-inch wide continuous strips.", "Gather strips and tie a tight overhand knot at one end.", "Separate into three sets of 2 strips and braid tightly.", "Tie a heavy knot at the bottom and trim fringe."]', 'Durable, machine-washable pet toy that costs zero dollars.', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=600&auto=format&fit=crop&q=80', 'approved', 89, 219);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (48, 16, 1, 'Ultra-Absorbent Scratch-Free Dusting & Car Cloths', 'reuse', 'Easy', 'Free', 0, '10 mins', '["100% cotton t-shirt", "Pinking shears or scissors"]', '["Cut t-shirt along side seams into 10x10 inch squares.", "Use pinking shears to reduce edge fraying.", "Stack in laundry area for cleaning countertops, electronics, windows, and buffing car wax."]', 'Completely eliminates disposable paper towels and chemical wipes.', 'https://images.unsplash.com/photo-1521572267360-ee0c2909d518?w=600&auto=format&fit=crop&q=80', 'approved', 96, 236);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (49, 17, 1, 'Denim Back-Pocket Wall Hanging Organizer', 'reuse', 'Easy', 'Low', 40, '30 mins', '["Worn denim jeans", "Scissors", "Wooden rod or hanger", "Needle & heavy thread or fabric glue"]', '["Carefully cut out the two rear pockets leaving a 1/2-inch denim border around each.", "Cut pocket strips from legs.", "Stitch or glue pockets onto a backing denim panel.", "Attach to a wooden dowel to hang on wall for phones, remotes, sunglasses, and keys."]', 'Leverages pre-sewn rugged pockets for instant wall storage.', 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=600&auto=format&fit=crop&q=80', 'approved', 18, 253);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (50, 17, 1, 'Heavy-Duty Thermal Pot Holders & Trivets', 'reuse', 'Medium', 'Free', 0, '35 mins', '["Denim leg sections", "Needle and thread", "Scissors"]', '["Cut four 8x8 inch squares from thick denim pant legs.", "Layer denim squares on top of each other (denim has exceptional natural thermal resistance).", "Stitch an ''X'' pattern through the layers and bind the border with a scrap denim strip."]', 'Protects kitchen countertops from hot pans without synthetic silicones.', 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=600&auto=format&fit=crop&q=80', 'approved', 25, 270);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (51, 17, 1, 'Rugged Denim Everyday Tote Bag', 'reuse', 'Advanced', 'Low', 50, '1 hour', '["Denim jeans waistband and legs", "Sewing kit or sewing machine"]', '["Cut legs off jeans just below zipper crotch line.", "Turn inside out and sew straight across the bottom hem.", "Use leg scraps to sew two 1-inch wide shoulder straps and attach to waistband."]', 'Fashionable, virtually indestructible tote bag with built-in functional pockets.', 'https://images.unsplash.com/photo-1542272604-787c3835535d?w=600&auto=format&fit=crop&q=80', 'approved', 32, 287);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (52, 18, 1, 'Hand-Mitt Venetian Blind & Baseboard Duster', 'reuse', 'Easy', 'Free', 0, '5 mins', '["Clean single sock (chenille or cotton works best)", "Water spray or polish"]', '["Slip sock over your hand like a glove.", "Spray lightly with water or wood polish.", "Grip individual blind slats between fingers and slide across to capture dust effortlessly."]', 'Fastest, most ergonomic way to clean awkward blinds and balustrades.', 'https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?w=600&auto=format&fit=crop&q=80', 'approved', 39, 304);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (53, 18, 1, 'Soothing Microwavable Heat Therapy Pack', 'reuse', 'Easy', 'Low', 30, '10 mins', '["Clean 100% cotton sock", "Dry uncooked rice (2 cups)", "Needle and thread or tight knot", "Dried lavender (optional)"]', '["Fill clean cotton sock with uncooked white or brown rice and lavender buds.", "Sew opening shut securely or tie an extremely tight knot.", "Microwave for 60 seconds for a soothing, reusable sore-muscle heating pad."]', 'Replaces electric heating pads or single-use chemical heat wraps.', 'https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?w=600&auto=format&fit=crop&q=80', 'approved', 46, 321);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (54, 18, 1, 'Crinkle Squeaker Pet Sock Toy', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Sock", "Empty plastic water bottle", "Scissors"]', '["Take an empty plastic water bottle (remove cap and ring).", "Slide bottle inside the sock.", "Tie a tight double knot at the open cuff end.", "Dogs love the crinkling crunch sound as they play."]', 'Safe, chewable pet stimulation from two discarded items.', 'https://images.unsplash.com/photo-1586350977771-b3b0abd50c82?w=600&auto=format&fit=crop&q=80', 'approved', 53, 338);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (55, 19, 1, 'Drawstring Reusable Produce Grocery Bags', 'reuse', 'Medium', 'Low', 30, '30 mins', '["Old sheet", "Scissors", "Safety pin", "Twine or cord", "Needle and thread"]', '["Cut sheet into 12x14 inch rectangles.", "Sew sides and bottom.", "Fold top rim down 1 inch to create a hollow channel and stitch.", "Thread cord through channel using safety pin to form a cinching drawstring."]', 'Replaces hundreds of single-use thin plastic grocery produce bags.', 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=600&auto=format&fit=crop&q=80', 'approved', 60, 355);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (56, 19, 1, 'Custom Padded Ironing Board Cover Replacement', 'repair', 'Medium', 'Free', 0, '35 mins', '["Sturdy cotton sheet", "Old ironing board", "Scissors", "Cord or elastic"]', '["Place old ironing board upside down on sheet and trace with 3 inches excess margin.", "Cut along trace.", "Hem edge with a safety-pinned drawstring cord.", "Fit over board and pull tight underneath."]', 'Restores scorched ironing boards for free using heat-resistant cotton.', 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=600&auto=format&fit=crop&q=80', 'approved', 67, 372);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (57, 19, 1, 'Children''s Magical Play Fort / Canopy Tent', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Bedsheet", "String", "Clothes pins", "Fairy lights"]', '["Tie string between two wall hooks or furniture pieces.", "Drape sheet over string and weight corners with books or pillows.", "Hang twinkle lights inside for reading nook."]', 'Spurs children''s creative imagination without buying plastic playhouses.', 'https://images.unsplash.com/photo-1522771739844-6a9f6d5f14af?w=600&auto=format&fit=crop&q=80', 'approved', 74, 389);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (58, 20, 1, 'Washable Reusable Wet/Dry Swiffer Mop Pad Refill', 'reuse', 'Easy', 'Free', 0, '20 mins', '["Old towel", "Scissors", "Sewing thread or safety pins"]', '["Cut towel into rectangles 2 inches wider than your flat mop head base.", "Hem edges to prevent unraveling.", "Tuck ends into mop head gripper slots. Machine wash and reuse hundreds of times."]', 'Saves tens of thousands of disposable single-use floor wipe refills.', 'https://images.unsplash.com/photo-1616627547584-bf28cee262db?w=600&auto=format&fit=crop&q=80', 'approved', 81, 406);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (59, 20, 1, 'Fast-Drying Hair Turban Towel Wrap', 'reuse', 'Medium', 'Low', 20, '25 mins', '["Terry towel", "Button", "Elastic hair tie loop", "Scissors", "Needle and thread"]', '["Cut towel into a tapered cone teardrop shape.", "Sew curved seam.", "Stitch small elastic loop at top tip and a button at the wide base to button closed on head."]', 'Gentle on hair and absorbs water faster than bulky bath towels.', 'https://images.unsplash.com/photo-1616627547584-bf28cee262db?w=600&auto=format&fit=crop&q=80', 'approved', 88, 423);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (60, 20, 1, 'Heavy-Duty Pet Washing & Muddy Paw Towel', 'reuse', 'Easy', 'Free', 0, '5 mins', '["Towel", "Scissors"]', '["Cut into convenient 18x18 inch squares.", "Keep in entryway or car trunk for wiping muddy dog paws after park walks."]', 'Diverts pet grime away from household linens.', 'https://images.unsplash.com/photo-1616627547584-bf28cee262db?w=600&auto=format&fit=crop&q=80', 'approved', 95, 440);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (61, 21, 1, 'Cozy Textured Throw Pillow Cushion Cover', 'reuse', 'Medium', 'Low', 50, '30 mins', '["Wool sweater", "Pillow insert (16x16 inch)", "Scissors", "Needle and yarn or sewing machine"]', '["Turn sweater inside out.", "Place pillow insert over the torso and mark outline with chalk.", "Cut squares and stitch three sides securely.", "Insert pillow and hand-stitch the fourth side shut."]', 'Adds high-end Scandinavian hygge warmth to sofas at zero cost.', 'https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=600&auto=format&fit=crop&q=80', 'approved', 17, 457);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (62, 21, 1, 'Felted Wool Winter Mittens', 'reuse', 'Medium', 'Low', 30, '40 mins', '["Wool sweater", "Washing machine (hot water to felt)", "Mitten template / paper", "Needle and embroidery thread"]', '["Wash sweater in hot water and tumble dry on high to ''felt'' the fibers so they won''t unravel when cut.", "Trace hand with thumb extended on sweater body.", "Cut out pairs and stitch around edge with blanket stitch."]', 'Extremely warm, naturally water-resistant winter mittens.', 'https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=600&auto=format&fit=crop&q=80', 'approved', 24, 124);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (63, 21, 1, 'Thermal Boot Toppers & Leg Warmers', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Sweater sleeves", "Scissors", "Needle and thread"]', '["Cut both sleeves off at the shoulder seam.", "Hem the cut raw edge with a quick stitch.", "Slide over calves and tuck top into boots."]', 'Chic cold-weather layering fashion made in 15 minutes.', 'https://images.unsplash.com/photo-1583743814966-8936f5b7be1a?w=600&auto=format&fit=crop&q=80', 'approved', 31, 141);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (64, 22, 1, 'Outdoor Picnic Blanket with Waterproof Backing', 'reuse', 'Medium', 'Low', 80, '45 mins', '["Sturdy curtain panel", "Shower curtain liner or tarp scrap", "Sewing pins", "Needle and thread"]', '["Cut curtain and waterproof backing to matching 5x6 ft dimensions.", "Place right sides facing each other and stitch outer edge, leaving a 6-inch gap.", "Invert through gap so pattern faces out, then topstitch perimeter."]', 'Durable lawn and beach picnic mat that keeps moisture off clothing.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=600&auto=format&fit=crop&q=80', 'approved', 38, 158);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (65, 22, 1, 'Under-Door Thermal Draft Stopper Snake', 'reuse', 'Easy', 'Free', 0, '20 mins', '["Curtain fabric", "Dry uncooked lentils/beans or fabric scraps", "Scissors", "Needle and thread"]', '["Cut a 8-inch wide strip matching your door width + 2 inches.", "Fold lengthwise right sides together and stitch long edge to form a tube.", "Turn right side out and pack tightly with dried beans and fabric trimmings.", "Stitch ends shut and lay against drafty door thresholds."]', 'Slashes winter heating bills by sealing drafty doorways.', 'https://images.unsplash.com/photo-1513694203232-719a280e022f?w=600&auto=format&fit=crop&q=80', 'approved', 45, 175);
