INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (67, 23, 1, 'Beeswax Reusable Food Storage Wraps', 'reuse', 'Easy', 'Low', 90, '25 mins', '["100% cotton fabric scraps", "Pure beeswax pellets", "Baking parchment paper", "Iron or oven"]', '["Cut cotton scraps into 8x8 or 10x10 inch squares with pinking shears.", "Place on baking sheet lined with parchment.", "Sprinkle beeswax pellets evenly over fabric.", "Warm in 90\u00b0C oven for 5 mins until melted, brush evenly and let cool."]', 'Replaces single-use cling film plastic wrap with washable, anti-bacterial beeswax wrap.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=600&auto=format&fit=crop&q=80', 'approved', 59, 209);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (68, 23, 1, 'Patchwork Quilted Drink Coasters', 'reuse', 'Medium', 'Free', 0, '30 mins', '["Fabric scraps", "Felt or scrap fleece for backing", "Needle and thread"]', '["Stitch colorful scrap strips together until a 5x5 inch square is formed.", "Sandwich thin batting or felt between patchwork and backing.", "Quilt across diagonal lines."]', 'Charming handcrafted table accents utilizing zero new materials.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=600&auto=format&fit=crop&q=80', 'approved', 66, 226);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (69, 23, 1, 'Aromatic Dried Herb Closet Sachets', 'reuse', 'Easy', 'Low', 30, '15 mins', '["Fabric scraps", "Dried lavender flowers or cloves", "Ribbon"]', '["Cut 4x4 inch fabric squares.", "Spoon 2 tablespoons dried lavender in center.", "Gather edges and tie firmly with ribbon. Hang in wardrobes to deter moths."]', 'Natural wardrobe deodorizer without synthetic chemicals.', 'https://images.unsplash.com/photo-1544816155-12df9643f363?w=600&auto=format&fit=crop&q=80', 'approved', 73, 243);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (70, 24, 1, 'Self-Regulating Slow Drip Plant Irrigator', 'reuse', 'Easy', 'Free', 0, '10 mins', '["PET water bottle", "Thumbtack or heated safety pin", "Water"]', '["Clean bottle thoroughly.", "Using a heated safety pin, puncture 3 tiny pinholes in the bottom half inch of the bottle and 1 in the cap.", "Fill with water, recap tightly.", "Bury the bottle upright 3 inches deep next to plant roots."]', 'Delivers root-zone moisture over 48 hours without evaporation loss.', 'https://images.unsplash.com/photo-1550989460-0adf9ea622e2?w=600&auto=format&fit=crop&q=80', 'approved', 80, 260);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (71, 24, 1, 'Hanging Vertical Garden Herb Planter', 'reuse', 'Medium', 'Low', 30, '25 mins', '["PET bottle", "Utility knife", "Jute twine", "Potting soil", "Seedlings"]', '["Cut a 3x5 inch rectangular window along the belly of the horizontal bottle.", "Poke drainage holes on opposite lower side.", "Thread cord through neck and base to hang in vertical ladders against sunny walls."]', 'Turns blank exterior balconies into productive vegetable vertical gardens.', 'https://images.unsplash.com/photo-1550989460-0adf9ea622e2?w=600&auto=format&fit=crop&q=80', 'approved', 87, 277);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (72, 24, 1, 'Wild Songbird Balcony Feeder', 'reuse', 'Easy', 'Low', 20, '20 mins', '["PET bottle", "2 wooden cooking spoons", "Birdseed", "Screw eye hook"]', '["Screw an eye hook into the bottle cap to hang.", "Make two paired cross-slits through bottle walls and push wooden spoons straight through so spoon bowl catches seed.", "Fill with birdseed and hang outdoors."]', 'Invites urban bird wildlife while reusing plastic bottles.', 'https://images.unsplash.com/photo-1550989460-0adf9ea622e2?w=600&auto=format&fit=crop&q=80', 'approved', 94, 294);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (73, 25, 1, 'Mini Greenhouse Cloche for Young Seedlings', 'reuse', 'Easy', 'Free', 0, '10 mins', '["2-liter bottle", "Scissors"]', '["Carefully cut off the bottom 3 inches of the bottle.", "Remove cap for ventilation or leave loose.", "Place over sensitive garden seedlings during cold nights or pest threats."]', 'Protects garden plants from frost, wind, and slugs like a commercial greenhouse dome.', 'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?w=600&auto=format&fit=crop&q=80', 'approved', 16, 311);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (74, 25, 1, 'Sub-Irrigated Self-Watering Planter Pot', 'reuse', 'Medium', 'Free', 0, '25 mins', '["2-liter bottle", "Cotton wick strip or thick yarn", "Potting soil", "Utility knife"]', '["Cut bottle in half crosswise.", "Invert top funnel section into bottom reservoir base.", "Thread cotton wick through bottle mouth down into water reservoir and up into soil chamber.", "Fill top with soil and plant."]', 'Capillary action draws exact water required by plant roots automatically.', 'https://images.unsplash.com/photo-1622483767028-3f66f32aef97?w=600&auto=format&fit=crop&q=80', 'approved', 23, 328);
