INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (119, 40, 1, 'Embossed Metal Botanical Plant Markers', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Clean aluminum can", "Scissors", "Ballpoint pen"]', '["Carefully cut top and bottom off can, then cut down the seam to flatten into an aluminum sheet.", "Cut into 1x5 inch stake strips with pointed bottoms.", "Use a dull ballpoint pen to deeply indent herb names (Rosemary, Mint, Thyme).", "Push into garden soil."]', '100% weatherproof, rust-proof permanent garden plant tags.', 'https://images.unsplash.com/photo-1581009146145-b5ef050c2e1e?w=600&auto=format&fit=crop&q=80', 'approved', 83, 393);
