INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (148, 50, 1, 'Mesh Jewelry & Earring Organizer', 'reuse', 'Easy', 'Low', 50, '30 mins', '["Old wooden frame (glass discarded)", "Metal wire mesh or decorative lace", "Staple gun or glue"]', '["Remove backing and broken glass safely.", "Stretch wire screen mesh or lace taut across the back of the frame.", "Staple in place.", "Hang on bedroom wall and hook earrings through mesh holes."]', 'Tangle-free, visual jewelry display for dressers.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 31, 186);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (149, 50, 1, 'Farmhouse Rustic Serving Tray with Handles', 'reuse', 'Medium', 'Low', 80, '40 mins', '["Sturdy picture frame", "Plywood backing", "2 cabinet handles", "Screws & paint"]', '["Secure wooden backing into frame.", "Paint or decoupage vintage wallpaper inside.", "Screw 2 cabinet handles to opposite short sides."]', 'Elegant tea and coffee serving tray made from recycled timber.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 38, 203);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (150, 50, 1, 'Dry-Erase Family Calendar & Memo Board', 'reuse', 'Easy', 'Low', 30, '20 mins', '["Picture frame with intact glass", "Printed calendar sheet or light fabric backing", "Dry-erase marker"]', '["Insert printed calendar template behind frame glass.", "Hang in kitchen.", "Write schedules, grocery lists, and reminders directly on glass with dry-erase marker. Wipes clean easily."]', 'Sleek reusable family schedule board.', 'https://images.unsplash.com/photo-1513519245088-0e12902e5a38?w=600&auto=format&fit=crop&q=80', 'approved', 45, 220);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (151, 51, 1, 'Ranger Bands (Indestructible Tactical Rubber Bands)', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Old bicycle inner tube", "Heavy scissors"]', '["Wash dirt off tube with warm water and dry.", "Cut tube crosswise into 1-inch and 2-inch rings.", "These are famous ''Ranger Bands'' used by outdoor survivalists: they never snap in sun, resist saltwater, and grip tenaciously."]', 'Replaces brittle rubber bands with lifetime heavy-duty elastic bands.', 'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=600&auto=format&fit=crop&q=80', 'approved', 52, 237);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (152, 51, 1, 'Non-Slip Jar Opening Gripper Pads', 'reuse', 'Easy', 'Free', 0, '5 mins', '["Inner tube", "Scissors"]', '["Cut a 6-inch flat square of rubber.", "Place over stubborn vacuum-sealed jar lids for 300% increased hand friction grip."]', 'Easily opens vacuum-sealed jars for elderly or arthritis sufferers.', 'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=600&auto=format&fit=crop&q=80', 'approved', 59, 254);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (153, 51, 1, 'Mountain Bike Chainstay Frame Guard', 'reuse', 'Easy', 'Free', 0, '15 mins', '["Inner tube", "Zip ties or electrical tape"]', '["Wrap tube tightly in overlapping spirals around bicycle chainstay bar.", "Fasten ends with zip ties to cushion bike frame against slapping chains."]', 'Silences noisy bike chains and protects frame paint from rock chips.', 'https://images.unsplash.com/photo-1485965120184-e220f721d03e?w=600&auto=format&fit=crop&q=80', 'approved', 66, 271);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (154, 52, 1, 'Deep-Detail Tile Grout & Faucet Cleaning Brush', 'reuse', 'Easy', 'Free', 0, '5 mins', '["Old toothbrush", "Baking soda & vinegar"]', '["Dip toothbrush in baking soda paste.", "Scrub bathroom faucet crevices, window tracks, tile grout, and sink drains.", "The angled head reaches crevices large sponges can never touch."]', 'Saves buying specialty chemical grout cleaning wands.', 'https://images.unsplash.com/photo-1559591937-e1032b4b4556?w=600&auto=format&fit=crop&q=80', 'approved', 73, 288);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (155, 52, 1, 'Fine Jewelry & Watch Band Polishing Wand', 'reuse', 'Easy', 'Free', 0, '10 mins', '["Soft-bristle worn toothbrush", "Gentle dish soap & warm water"]', '["Soak rings or stainless steel watch bands in warm soapy water.", "Gently brush under diamond settings and between metal watch links to loosen skin oils and grime."]', 'Safely restores high-shine brilliance to fine jewelry.', 'https://images.unsplash.com/photo-1559591937-e1032b4b4556?w=600&auto=format&fit=crop&q=80', 'approved', 80, 305);
INSERT INTO `ideas` (`id`, `item_id`, `user_id`, `title`, `type`, `difficulty`, `cost_level`, `estimated_cost`, `time_required`, `materials_json`, `steps_json`, `summary`, `image_url`, `status`, `likes_count`, `views_count`) VALUES (156, 52, 1, 'Bicycle & Chainsaw Chain Degreasing Tool', 'reuse', 'Easy', 'Free', 0, '15 mins', '["2 old toothbrushes", "Electrical tape or zip tie", "Degreaser"]', '["Tape two toothbrushes together with bristles facing each other.", "Clamp over bike chain and spin pedals through degreaser for instant 360-degree cleaning."]', 'Professional cleaning tool made for zero cost.', 'https://images.unsplash.com/photo-1559591937-e1032b4b4556?w=600&auto=format&fit=crop&q=80', 'approved', 87, 322);
